  // --- Apply machined-metal PBR + accent rim to every mesh ---
  const processedMaterials = [];

  badgeMesh.traverse((child) => {
    if (!child.isMesh) return;

    const srcMat = child.material;

    // Build a fresh node material so we can inject emissiveNode
    const nodeMat = new THREE.MeshStandardNodeMaterial();

